CREATE TABLE IF NOT EXISTS "model_probe_results" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "site_id" INTEGER NOT NULL, "account_id" INTEGER, "model_name" TEXT NOT NULL, "status" TEXT NOT NULL, "latency_ms" INTEGER, "http_status" INTEGER, "failure_kind" TEXT, "reason" TEXT, "endpoint_used" TEXT, "prompt_used" TEXT, "user_agent_used" TEXT, "checked_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("account_id") REFERENCES "accounts"("id") ON DELETE SET NULL, FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "model_probe_results_site_model_unique" ON "model_probe_results" ("site_id", "model_name");
CREATE INDEX "model_probe_results_account_id_idx" ON "model_probe_results" ("account_id");
CREATE INDEX "model_probe_results_checked_at_idx" ON "model_probe_results" ("checked_at");
CREATE INDEX "model_probe_results_model_name_idx" ON "model_probe_results" ("model_name");
CREATE INDEX "model_probe_results_site_id_idx" ON "model_probe_results" ("site_id");
CREATE INDEX "model_probe_results_status_idx" ON "model_probe_results" ("status");
